159	func TestOpenAllowsConfirmedTransferHistory(t *testing.T) {
160		// 样品完成旧交接后分装，再发起新交接：旧交接的持有人、地点、数量
161		// 与样品当前状态不同是正常历史，不应拒绝打开。
162		dir := t.TempDir()
163		path := filepath.Join(dir, "data.json")
164		s, err := Open(path)
165		if err != nil {
166			t.Fatal(err)
167		}
168		mustRegister(t, s, "P", "7.500", "张三", "A")
169		at := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
170		if _, err := s.Handover(HandoverInput{
171			TransferID: "T-old", SampleID: "P",
172			FromHolder: "张三", FromLocation: "A",
173			ToHolder: "李四", ToLocation: "B", HandedOverAt: at,
174		}); err != nil {
175			t.Fatal(err)
176		}
177		if _, err := s.Confirm(ConfirmInput{"T-old", "李四", "B", at.Add(time.Hour)}); err != nil {
178			t.Fatal(err)
179		}
180		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "C", Qty: "2.500"}}}); err != nil {
181			t.Fatal(err)
182		}
183		if _, err := s.Handover(HandoverInput{
184			TransferID: "T-new", SampleID: "P",
185			FromHolder: "李四", FromLocation: "B",
186			ToHolder: "王五", ToLocation: "C", HandedOverAt: at.Add(2 * time.Hour),
187		}); err != nil {
188			t.Fatal(err)
189		}
190	
191		s2, err := Open(path)
192		if err != nil {
193			t.Fatalf("含已确认历史交接与当前待确认交接的合法文件应能打开: %v", err)
194		}
195		p, err := s2.GetSample("P")
196		if err != nil {
197			t.Fatal(err)
198		}
199		if p.PendingTransfer == nil || p.PendingTransfer.TransferID != "T-new" {
200			t.Fatalf("重开后当前待确认交接应保留: %+v", p.PendingTransfer)
201		}
202		old, err := s2.GetTransfer("T-old")
203		if err != nil {
204			t.Fatal(err)
205		}
206		if !old.Confirmed {
207			t.Fatalf("旧交接应保持已确认: %+v", old)
208		}
209	}
