211	func TestOpenAllowsEmptyCollections(t *testing.T) {
212		for name, content := range map[string]string{
213			"集合整体缺省":   `{"version": 1}`,
214			"集合为 null": `{"version": 1, "samples": null, "transfers": null}`,
215			"集合为空对象":   `{"version": 1, "samples": {}, "transfers": {}}`,
